class SearchCandidate { const SearchCandidate({required this.id, required this.title, this.description = ''}); final String id, title, description; }
class RankedSearchCandidate { const RankedSearchCandidate(this.candidate, this.score); final SearchCandidate candidate; final int score; }
class UniversalSearchRanker { const UniversalSearchRanker(); List<RankedSearchCandidate> rank({required String query, required Iterable<SearchCandidate> candidates, int limit = 20}) { if (limit < 0) throw ArgumentError.value(limit); final q = query.trim().toLowerCase(); if (q.isEmpty || limit == 0) return const []; final seen = <String>{}; final out = <RankedSearchCandidate>[]; for (final c in candidates) { if (c.id.trim().isEmpty || !seen.add(c.id)) continue; final t = c.title.trim().toLowerCase(); final d = c.description.toLowerCase(); final score = t == q ? 60 : t.startsWith(q) ? 40 : t.contains(q) ? 30 : d.contains(q) ? 12 : 0; if (score > 0) out.add(RankedSearchCandidate(c, score)); } out.sort((a,b) { final s = b.score.compareTo(a.score); return s != 0 ? s : a.candidate.id.compareTo(b.candidate.id); }); return List.unmodifiable(out.take(limit)); } }
